insert into public.kanji_structure(kanji_id,radical_form,radical_base,radical_position,radical_rule,components,decomposition,needs_review)
select k.id,r.a[2],f.base_char,case r.a[3] when 'h' then 'へん' when 't' then 'つくり' when 'k' then 'かんむり' when 'a' then 'あし' when 'm' then 'かまえ' when 'n' then 'にょう' when 'r' then 'たれ' end,case r.a[4] when 'g' then 'general' else 'tradit' end,case when r.a[5] ~ 'CDP' then '{}'::text[] else regexp_split_to_array(r.a[5],'') end,case when r.a[5] ~ 'CDP' or r.a[6] ~ 'CDP' or r.a[6]='' then '[]'::jsonb else (select jsonb_agg(jsonb_build_object('c',split_part(e,':',1),'p',to_jsonb(regexp_split_to_array(split_part(e,':',2),'')))) from unnest(string_to_array(r.a[6],',')) e) end,r.a[5] ~ 'CDP' from (select string_to_array(l,'|') as a from unnest(string_to_array($d$一|一|-|g||
七|一|-|t|一乙|
